import math

def matrixfy(name: str) -> list[list[str]] | str:
    if len(name) == 0:
        return "name must be at least one letter"

    n = len(name)
    size = math.ceil(math.sqrt(n))

    matrix = []
    index = 0

    for i in range(size):
        row = []
        for j in range(size):
            if index < n:
                row.append(name[index])
                index += 1
            else:
                row.append('.')
        matrix.append(row)

    return matrix
